import { Incident } from "../../entities/incident";
import styles from "./IncidentsTable.module.css";

type Props = {
  incidents: Incident[];
};

export const IncidentsTable = ({ incidents }: Props) => {
  return (
    <div className={styles.wrapper}>
      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Дата</th>
            <th>Приоритет</th>
            <th>Описание</th>
            <th>Статус сервиса</th>
            <th>Статус тикета</th>
            <th>Филиал</th>
          </tr>
        </thead>
        <tbody>
          {incidents.map((i) => (
            <tr key={i.id}>
              <td>{i.id}</td>
              <td>{i.createdAt}</td>
              <td
                className={
                  i.priority === 1
                    ? styles.priority1
                    : i.priority === 2
                    ? styles.priority2
                    : styles.priority3
                }
              >
                {i.priority}
              </td>
              <td>{i.description}</td>
              <td>{i.serviceStatus}</td>
              <td>{i.ticketStatus}</td>
              <td>{i.branch}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};
